def calculator(expression: str) -> str:
    left, right = expression.split("+")
    return str(int(left) + int(right))


def mock_model(messages: list[dict[str, str]]) -> dict[str, str]:
    if not any(message["role"] == "tool" for message in messages):
        return {"type": "tool_call", "name": "calculator", "args": "20+22"}
    observation = messages[-1]["content"]
    return {"type": "final", "content": f"The answer is {observation}."}


def run_agent() -> None:
    messages = [{"role": "user", "content": "What is 20 + 22?"}]
    for step in range(3):
        action = mock_model(messages)
        print(f"step={step} action={action['type']}")
        if action["type"] == "final":
            print(f"answer={action['content']}")
            return
        observation = calculator(action["args"])
        print(f"tool={action['name']} observation={observation}")
        messages.append({"role": "tool", "content": observation})
    raise RuntimeError("agent exceeded step limit")


run_agent()
